local verifiedSpellDescriptions = {
    [1671] = { en = "Bashes the target with your shield for $s2 damage.  It also interrupts spellcasting and prevents any spell in that school from being cast for $d.", description = "Colpisce il bersaglio con lo scudo, infliggendo $s2 danni. Interrompe inoltre il lancio degli incantesimi e impedisce di lanciare incantesimi di quella scuola per $d." },
    [1714] = { en = "Forces the target to speak in Demonic, increasing the casting time of all spells by $s1%. Only one Curse per Warlock can be active on any one target. Lasts $d.", description = "Costringe il bersaglio a parlare in Demoniaco, aumentando del $s1% il tempo di lancio di tutti gli incantesimi. Un warlock può avere attiva una sola Maledizione su ciascun bersaglio. Dura $d." },
    [1850] = { en = "Increases movement speed by $s1% for $d.  Does not break prowling.", description = "Aumenta la velocità di movimento del $s1% per $d.  Non interrompe il furtivismo." },
    [2094] = { en = "Blinds the target, causing it to wander disoriented for up to $d.  Any damage caused will remove the effect.", description = "Acceca il bersaglio, facendolo vagare disorientato per un massimo di $d.  Qualsiasi danno inflitto rimuove l'effetto." },
    [2139] = { en = "Counters the enemy's spellcast, preventing any spell from that school of magic from being cast for $d.  Generates a high amount of threat.", description = "Contrasta il lancio dell'incantesimo nemico, impedendo di lanciare incantesimi di quella scuola per $d.  Genera molta minaccia." },
    [2812] = { en = "Sends bolts of holy power in all directions, causing $s1 Holy damage to all Undead and Demon targets within $a1 yds and stunning them for $429147d.", description = "Scaglia raggi di potere sacro in tutte le direzioni, infliggendo $s1 danni sacri a tutti i bersagli Non morti e Demoni entro $a1 metri e stordendoli per $429147d." },
    [2826] = { en = "NYI.", description = "Non ancora implementato." },
    [3256] = { en = "Reduces Strength by $s1, Agility by $s2, and Intellect by $s3 for all enemies in a selected area for $d.", description = "Riduce la Forza di $s1, l'Agilità di $s2 e l'Intelletto di $s3 a tutti i nemici in un'area selezionata per $d." },
    [3360] = { en = "Curses an enemy with the Eye of Paleth, reducing the Physical damage it deals by $10653s1 and slowing its spellcasting by $10653s2% for $10653d.", description = "Maledice un nemico con l'Occhio di Paleth, riducendone i danni fisici di $10653s1 e rallentandone il lancio degli incantesimi del $10653s2% per $10653d." },
    [3584] = { en = "Infects an enemy for $d., causing it to inflict $3585s1 Nature damage to its nearby allies every $t1 sec.", description = "Infetta un nemico per $d., facendogli infliggere $3585s1 danni da natura agli alleati vicini ogni $t1 s." },
    [3674] = { en = "Fires a Black Arrow into the target, slowing the target's movement speed by $s1%, causing $o2 Shadow damage and draining $o3 mana over $d.", description = "Scaglia una Freccia Nera contro il bersaglio, riducendone la velocità di movimento del $s1%, infliggendo $o2 danni da ombra e prosciugando $o3 mana in $d." },
    [4068] = { en = "Inflicts $s1 Fire damage and stuns targets for $d in a 3 yard radius. Any damage will break the effect.", description = "Infligge $s1 danni da fuoco e stordisce i bersagli per $d entro un raggio di 3 metri. Qualsiasi danno interrompe l'effetto." },
