    [5599] = { en = "A targeted party member is protected from all physical attacks for $d, but during that time they cannot attack or use physical abilities.  Players may only have one Blessing on them per Paladin at any one time.  Applies Forbearance for $25771d. Cannot be cast while Forbearance is active.", description = "Protegge un membro del gruppo dagli attacchi fisici per $d, ma per tutta la durata gli impedisce di attaccare o usare abilità fisiche.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta.  Applica Resa dei Conti per $25771d. Non può essere lanciato mentre Resa dei Conti è attiva." },
    [5642] = { en = "Increases your damage with Guns by $s1 and have a 2% chance of stunning the target for 5 seconds.", description = "Aumenta di $s1 i danni inflitti con le armi da fuoco e conferisce una probabilità del 2% di stordire il bersaglio per 5 s." },
    [5755] = { en = "Increases your damage with Bows and by $s1 and has a 2% chance of bleeding the target for 180 damage over 10 seconds.", description = "Aumenta di $s1 i danni inflitti con gli archi e conferisce una probabilità del 2% di far sanguinare il bersaglio, infliggendo 180 danni in 10 s." },
    [5757] = { en = "Increases your attack rating with Crossbows by $s1.", description = "Aumenta di $s1 la tua abilità con le balestre." },
