    [6940] = { en = "Places a Blessing on the party member, transfering $s1 damage taken per hit to the caster.  Lasts $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Benedice il membro del gruppo, trasferendo all'incantatore $s1 danni subiti per colpo.  Dura $d.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta." },
