    [9132] = { en = "Improves your chance to get a critical strike with ranged weapons by ${$s1}.1%.", description = "Aumenta di ${$s1}.1% la probabilità di infliggere un colpo critico con le armi a distanza." },
    [10670] = { en = "Increases Strength by $s1 when consumed.", description = "Aumenta la Forza di $s1 quando viene consumato." },
    [10671] = { en = "Increases Stamina by $s1 when consumed.", description = "Aumenta la Tempra di $s1 quando viene consumato." },
