    [11730] = { en = "Creates a Major Healthstone that can be used to instantly restore $11732s1 health.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra della Salute Maggiore che ripristina istantaneamente $11732s1 salute.\r\n            Gli oggetti evocati scompaiono se rimani disconnesso per più di 15 minuti." },
