    [20217] = { en = "Places a Blessing on the friendly target, increasing total stats by $s1% for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Benedice il bersaglio amico, aumentando del $s1% tutte le statistiche per $d.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta." },
