    [20559] = { en = "A mocking attack that causes $s1 damage, a moderate amount of threat and forces the target to focus attacks on you for $d.", description = "Un attacco provocatorio che infligge $s1 danni, genera una quantità moderata di minaccia e costringe il bersaglio a concentrarsi su di te per $d." },
    [20607] = { en = "Increased Staves +$s1.", description = "Abilità con i bastoni aumentata di +$s1." },
    [20688] = { en = "Shoots a flaming arrow at an enemy, inflicting weapon damage plus $s1. All damage inflicted is based upon Fire magic.", description = "Scaglia una freccia infuocata contro un nemico, infliggendo i danni dell'arma più $s1. Tutti i danni inflitti sono da magia del fuoco." },
    [20927] = { en = "Increases chance to block by $s1% for $d, and deals $s2 Holy damage for each attack blocked while active. Damage caused by Holy Shield causes 20% additional threat.", description = "Aumenta del $s1% la probabilità di blocco per $d e infligge $s2 danni sacri per ogni attacco bloccato mentre è attivo. I danni di Scudo Sacro generano il 20% di minaccia aggiuntiva." },
    [21052] = { en = "DND", description = "Non eliminare." },
    [21156] = { en = "Decreases threat generated by $s1%.", description = "Riduce del $s1% la minaccia generata." },
    [21562] = { en = "Power infuses all party and raid members, increasing their Stamina by $s1 for $d.", description = "Il potere pervade tutti i membri del gruppo e del raid, aumentando la loro Tempra di $s1 per $d." },
    [21748] = { en = "Deals $s1 damage to nearby enemies, knocking them down for $d.", description = "Infligge $s1 danni ai nemici vicini e li atterra per $d." },
    [21849] = { en = "Gives the Gift of the Wild to all party and raid members, increasing armor by $s1, all attributes by $s2 and all resistances by $s3 for $d.", description = "Conferisce il Dono della Natura Selvaggia a tutti i membri del gruppo e del raid, aumentando di $s1 l'armatura, di $s2 tutti gli attributi e di $s3 tutte le resistenze per $d." },
    [22351] = { en = "Causes $s1 Nature damage to any creature that strikes the caster.", description = "Infligge $s1 danni da natura a ogni creatura che colpisce l'incantatore." },
    [22371] = { en = "Decreases the Magical damage dealt by the target by $s1 for $d.", description = "Riduce di $s1 i danni magici inflitti dal bersaglio per $d." },
    [22751] = { en = "Health increased by $s0%.\r\n", description = "Salute aumentata del $s0%." },
    [22801] = { en = "Increases the speed of your Ghost Wolf ability by $s1%.", description = "Aumenta del $s1% la velocità della tua abilità Lupo Fantasma." },
    [22817] = { en = "Attack power increased by $s1 and spell damage and healing increased by up to $s3.", description = "Potenza d'attacco aumentata di $s1; danni degli incantesimi e cure aumentati fino a $s3." },
    [22855] = { en = "Restores $s1 mana per 5 sec to your Imp.", description = "Ripristina $s1 mana ogni 5 s al tuo Imp." },
    [22910] = { en = "Place a fire trap that will burn the first enemy to approach for $14301o1 Fire damage over $14301d.  Trap will exist for $d.  Traps can only be placed when out of combat.  Only one trap can be active at a time.", description = "Piazza una trappola di fuoco che brucia il primo nemico che vi si avvicina, infliggendo $14301o1 danni da fuoco in $14301d.  La trappola rimane per $d. Puoi piazzare trappole solo fuori dal combattimento e averne attiva una sola alla volta." },
    [23723] = { en = "Quickens the mind, increasing the Mage's casting speed by $s1% for $d.", description = "Ravviva la mente, aumentando del $s1% la velocità di lancio degli incantesimi del mago per $d." },
    [23726] = { en = "Increases the chance to apply Rogue poisons to your target by $s1% for $d.", description = "Aumenta del $s1% la probabilità di applicare i veleni da scasso al bersaglio per $d." },
    [23733] = { en = "Energizes a Paladin with light, increasing melee attack speed by $s2% and spell casting speed by $s1% for $d.", description = "Infuoca un paladino con la Luce, aumentando del $s2% la velocità d'attacco in mischia e del $s1% la velocità di lancio degli incantesimi per $d." },
    [23782] = { en = "Heals yourself for 15%, and increases your maximum health by 15% for $d.", description = "Ti cura del 15% e aumenta del 15% la tua salute massima per $d." },
    [24294] = { en = "Increases all damage caused against Beasts, Giants and Dragonkin targets by $s1% and increases critical damage caused against Beasts, Giants and Dragonkin targets by an additional $s2%.", description = "Aumenta dell'$s1% tutti i danni inflitti a Bestie, Giganti e Dragonkin e aumenta di un ulteriore $s2% i danni critici contro questi bersagli." },
    [24382] = { en = "Increases the player's Spirit by $s1 and Stamina by $s2 for $d.  You can only have the effect of one Zanza potion at a time.", description = "Aumenta di $s1 lo Spirito e di $s2 la Tempra del giocatore per $d.  Puoi avere attivo un solo effetto di pozione Zanza alla volta." },
    [24417] = { en = "Increases the chance that the player will reflect hostile spells cast on them by $s1% for $d. Will automatically reflect the first offensive spell cast against the user. Only one type of Zanza potion may be active at any given time.", description = "Aumenta del $s1% la probabilità di riflettere gli incantesimi ostili per $d. Riflette automaticamente il primo incantesimo offensivo lanciato contro chi la usa. Può essere attivo un solo tipo di pozione Zanza alla volta." },
    [24499] = { en = "Increases the damage dealt by your Lightning Shield spell by $s1% for $d.", description = "Aumenta del $s1% i danni inflitti dal tuo incantesimo Scudo di Fulmini per $d." },
    [24998] = { en = "Increases healing done by magical spells and effects by up to $s1 for $d.", description = "Aumenta fino a $s1 le cure degli incantesimi e degli effetti magici per $d." },
    [25718] = { en = "Decreases the frost resistance of your spell targets by $s1.", description = "Riduce di $s1 la resistenza al gelo dei bersagli dei tuoi incantesimi." },
    [25782] = { en = "Gives all members of the raid or group that share the same class with the target the Greater Blessing of Might, increasing melee attack power by $s1 for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Conferisce Benedizione della Potenza Superiore a tutti i membri del gruppo o del raid della stessa classe del bersaglio, aumentando di $s1 la potenza d'attacco in mischia per $d.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta." },
    [25894] = { en = "Gives all members of the raid or group that share the same class with the target the Greater Blessing of Wisdom, restoring $s1 mana every $t1 seconds for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Conferisce Benedizione della Saggezza Superiore a tutti i membri del gruppo o del raid della stessa classe del bersaglio, ripristinando $s1 mana ogni $t1 s per $d.  Ogni paladino può avere attiva su un giocatore una sola Benedizione alla volta." },
    [26166] = { en = "Increases damage done by magical spells and effects by up to $s1, and decreases the magical resistances of your spell targets by $s2 for $d.", description = "Aumenta fino a $s1 i danni inflitti dagli incantesimi e dagli effetti magici e riduce di $s2 le resistenze magiche dei bersagli per $d." },
    [26180] = { en = "A stinging shot that puts the target to sleep for $d.  Any damage will cancel the effect. ", description = "Un colpo pungente che addormenta il bersaglio per $d.  Qualsiasi danno interrompe l'effetto." },
    [26376] = { en = "Casts a spell when you do something.", description = "Lancia un incantesimo quando esegui un'azione." },
    [26540] = { en = "Calls down a rain of moonlight, burning all enemies in a selected area for $s1 Arcane damage every $t1 sec. for $d.", description = "Fa piovere luce lunare, bruciando tutti i nemici nell'area selezionata e infliggendo $s1 danni arcani ogni $t1 s per $d." },
    [27117] = { en = "Permanently enchant a shield to give +$13690s1% chance to block.", description = "Incanta permanentemente uno scudo, conferendo una probabilità del +$13690s1% di bloccare." },
    [27681] = { en = "Power infuses all party and raid members, increasing their Spirit by $s1 for $d.", description = "Il potere pervade tutti i membri del gruppo e del raid, aumentando il loro Spirito di $s1 per $d." },
    [27720] = { en = "Increases Defense by $s1 for $d.", description = "Aumenta la Difesa di $s1 per $d." },
    [27721] = { en = "Increases damage done from spells by up to $s1 for $d.", description = "Aumenta fino a $s1 i danni inflitti dagli incantesimi per $d." },
    [27722] = { en = "Increases healing done by magical spells by up to $s1 for $d.", description = "Aumenta fino a $s1 le cure degli incantesimi magici per $d." },
    [27779] = { en = "Absorbs $s1 damage.", description = "Assorbe $s1 danni." },
    [27807] = { en = "Inflicts $s2 Nature damage and an additional $s1 damage every $t1 sec. to enemies in a cone in front of the caster. Nature resistance is reduced by $s2. Lasts $d.", description = "Infligge $s2 danni da natura e altri $s1 danni ogni $t1 s ai nemici in un cono di fronte all'incantatore. Riduce di $s2 la resistenza alla natura. Dura $d." },
    [27825] = { en = "In a whirlwind of steel you attack up to $i enemies within $a1 yards, causing weapon damage to each enemy.", description = "Con un turbine d'acciaio, attacchi fino a $i nemici entro $a1 metri, infliggendo a ciascuno i danni dell'arma." },
    [27900] = { en = "Reduces all spell damage taken by $s1%.", description = "Riduce del $s1% tutti i danni degli incantesimi subiti." },
    [28780] = { en = "Increases healing done by the next 5 spells by up to $s1 for $d.", description = "Aumenta fino a $s1 le cure dei prossimi 5 incantesimi per $d." },
    [29113] = { en = "Increases damage done to Undead and Demons by magical spells and effects by up to $s1.  Allows the acquisition of Scourgestones on behalf of the Argent Dawn.", description = "Aumenta fino a $s1 i danni inflitti da incantesimi ed effetti magici contro Non morti e Demoni. Permette di ottenere Pietre del Flagello per conto dell'Alba d'Argento." },
    [29163] = { en = "Launches a bolt of frost at the enemy, causing $s2 Frost damage and slowing movement speed by $s1% for $d.", description = "Scaglia un dardo di gelo contro il nemico, infliggendo $s2 danni da gelo e riducendone la velocità di movimento del $s1% per $d." },
    [29166] = { en = "Increases the target's Mana regeneration by $s2% and allows $s1% of the target's Mana regeneration to continue while casting.  Lasts $d.", description = "Aumenta del $s2% la rigenerazione del mana del bersaglio e permette di mantenerne attivo durante il lancio il $s1%.  Dura $d." },
    [29189] = { en = "Reduces the threat generated by your healing spells by $s1%.", description = "Riduce del $s1% la minaccia generata dai tuoi incantesimi curativi." },
    [29192] = { en = "Increases the melee attack power bonus of your Windfury Totem by $s1% and increases the damage caused by your Flametongue Totem by $s2%.", description = "Aumenta del $s1% il bonus alla potenza d'attacco in mischia del tuo Totem del Vento Furioso e del $s2% i danni inflitti dal tuo Totem Lingua di Fuoco." },
    [167152] = { en = "Restores $o3% health and $o1% Mana over $d. Must remain seated while drinking.", description = "Ripristina $o3% salute e $o1% mana in $d. Devi rimanere seduto mentre bevi." },
    [363731] = { en = "Health increased by $s1%.\r\n", description = "Salute aumentata del $s1%." },
    [363757] = { en = "Health increased by $s1%.", description = "Salute aumentata del $s1%." },
    [400023] = { en = "Any attack which would otherwise kill you will instead reduce you to 10% of your maximum health. In addition, all damage taken will be reduced by up to $400024s1% for $400024d.  This effect cannot occur more than once per minute.", description = "Qualsiasi attacco che dovrebbe ucciderti ti riduce invece al 10% della salute massima. Inoltre, riduce fino al $400024s1% tutti i danni subiti per $400024d. L'effetto può attivarsi al massimo una volta al minuto." },
    [400669] = { en = "Gives your Chill effects a chance to grant you the Fingers of Frost effect, which treats your next spells cast as if the target were Frozen.  Lasts $d.", description = "I tuoi effetti di Congelamento hanno una probabilità di conferire l'effetto Dita di Gelo, che fa sì che i tuoi prossimi incantesimi considerino il bersaglio congelato.  Dura $d." },
    [401977] = { en = "Creates a shadowy fiend to attack the target.  Caster receives $401988s1% mana when the Shadowfiend attacks. Lasts $d.", description = "Evoca un demone ombroso che attacca il bersaglio.  L'incantatore riceve il $401988s1% del mana quando il demone attacca. Dura $d." },
    [402801] = { en = "Animate $s1 skeletons that attack your current target with a mace, sword, and axe, reducing the target's attack speed, attack power, and armor respectively.", description = "Anima $s1 scheletri che attaccano il bersaglio attuale con una mazza, una spada e un'ascia, riducendone rispettivamente la velocità d'attacco, la potenza d'attacco e l'armatura." },
    [408699] = { en = "Your Ambush and Backstab hits unbalance your target, increasing the time between their melee attacks by $408699s1%, and reducing movement speed by $408699s2% for $408699d.", description = "I tuoi attacchi Imboscata e Backstab sbilanciano il bersaglio, aumentando del $408699s1% l'intervallo tra i suoi attacchi in mischia e riducendone la velocità di movimento del $408699s2% per $408699d." },
    [409333] = { en = "For the next $409324d, $409324s1% of your damage is converted to healing on up to 3 nearby party members, and $409324s2% of your healing is converted to damage on your most recent Flame Shock target.", description = "Per i prossimi $409324d, il $409324s1% dei tuoi danni si converte in cure per un massimo di 3 membri del gruppo vicini, mentre il $409324s2% delle tue cure si converte in danni contro il bersaglio più recente del tuo Shock di Fiamma." },
    [409593] = { en = "You attempt to finish off a wounded target, firing a ranged attack dealing $s2% weapon damage plus ${$m1/100*$m2/100*$<damagepower>}. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health.", description = "Tenti di finire un bersaglio ferito con un attacco a distanza che infligge danni pari al $s2% dei danni dell'arma più ${$m1/100*$m2/100*$<damagepower>}. Tiro Mortale non ha gittata minima. Il tempo di recupero di Tiro Mortale si azzera se colpisce un nemico con il 20% o meno di salute." },
    [411124] = { en = "Reduces all damage taken by $s1%.", description = "Riduce del $s1% tutti i danni subiti." },
    [412018] = { en = "Each time the target takes damage they gain a Sacred Shield, absorbing $s1 damage and increasing the paladin's chance to critically hit with Flash of Light by $s2% for up to $d.  They cannot gain this effect more than once every 6 sec.  Lasts $d.\r\n", description = "Ogni volta che il bersaglio subisce danni, riceve uno Scudo Sacro che assorbe $s1 danni e aumenta del $s2% la probabilità del paladino di infliggere un colpo critico con Lampo di Luce per un massimo di $d. L'effetto non può attivarsi sul bersaglio più di una volta ogni 6 s.  Dura $d.\r\n            " },
    [414684] = { en = "Burns the enemy for ${$m2*$<damagepower>/100} to ${$M2*$<damagepower>/100} Nature damage and then an additional ${$m1*4*$<damagepower>/100} Nature damage over $d.", description = "Brucia il nemico, infliggendo da ${$m2*$<damagepower>/100} a ${$M2*$<damagepower>/100} danni da natura, poi altri ${$m1*4*$<damagepower>/100} danni da natura in $d." },
    [425096] = { en = "Attacks made while stealthed and for 6 seconds after breaking stealth cause an additional $s1% damage.", description = "Gli attacchi eseguiti in furtività e per 6 s dopo averla interrotta infliggono il $s1% di danni aggiuntivi." },
    [426320] = { en = "Burns the enemy for ${$m1*$<power>/100*$<mult>} Shadowflame damage and then an additional ${$m2*5*$<power>/100} Shadowflame damage over $d.\r\n\r\nShadowflame triggers and benefits from all effects that modify or interact with Immolate, or with Affliction, Destruction, Fire, or Shadow spells, but only one of Immolate or Shadowflame per Warlock can be active on any target. In addition, Shadowflame can trigger your Improved Shadow Bolt talent and causes it to have $426454s2 additional charges.", description = "Brucia il nemico, infliggendo ${$m1*$<power>/100*$<mult>} danni da Ombrafiamma e poi altri ${$m2*5*$<power>/100} danni da Ombrafiamma in $d.\r\n\r\nOmbrafiamma attiva e beneficia di tutti gli effetti che modificano o interagiscono con Immolate oppure con gli incantesimi di Afflizione, Demonologia, Fuoco o Ombra; tuttavia, su ciascun bersaglio un warlock può mantenere attivo Immolate oppure Ombrafiamma. Inoltre, Ombrafiamma può attivare il talento Dardo d'Ombra Migliorato e gli conferisce $426454s2 cariche aggiuntive." },
    [429145] = { en = "Sends bolts of holy power in all directions, causing $s1 Holy damage to all targets within $a1 yds and Stunning Demon and Undead targets for $429147d.", description = "Scaglia raggi di potere sacro in tutte le direzioni, infliggendo $s1 danni sacri a tutti i bersagli entro $a1 metri e stordendo i Demoni e i Non morti per $429147d." },
    [430352] = { en = "Increases all damage and healing done by $s1% for $d.", description = "Aumenta del $s1% tutti i danni e le cure inflitti per $d." },
    [435968] = { en = "Inflicts $s1 fire damage to those in the blast radius plus an additional $s3 nature damage every 2 sec for 10 seconds. Also reduces the movement speed of affected targets by 25% for $d. ", description = "Infligge $s1 danni da fuoco a chi si trova nell'area dell'esplosione e altri $s3 danni da natura ogni 2 s per 10 s. Riduce inoltre del 25% la velocità di movimento dei bersagli colpiti per $d." },
    [436892] = { en = "Increases your movement speed by $s1% while outdoors in Cat Form and increases your chance to dodge while in Cat Form by $24864s1%.", description = "Aumenta del $s1% la velocità di movimento all'aperto in Forma Felina e del $24864s1% la probabilità di schivare in Forma Felina." },
    [437169] = { en = "Begins a ritual that creates a summoning portal.  The summoning portal can be used by 2 party or raid members to summon a targeted party or raid member.  The ritual portal requires the caster and 2 additional party or raid members to complete.  In order to participate, all players must be out of combat and right-click the portal and not move until the ritual is complete.", description = "Avvia un rituale che crea un portale d'evocazione. Il portale può essere usato da 2 membri del gruppo o del raid per evocare un membro scelto. Per completare il rituale servono l'incantatore e altri 2 membri del gruppo o del raid. Per partecipare, tutti i giocatori devono essere fuori dal combattimento, fare clic destro sul portale e restare immobili fino al termine del rituale." },
    [437390] = { en = "The caster spits a lethargic poison at players, inflicting $s1 Nature damage every $t1 sec for $d. This poison reduces hit chance by $s2% and increases ability costs by $s3%.", description = "L'incantatore sputa un veleno debilitante sui giocatori, infliggendo $s1 danni da natura ogni $t1 s per $d. Il veleno riduce del $s2% la probabilità di colpire e aumenta del $s3% il costo delle abilità." },
    [437532] = { en = "The shade releases a screeching howl striking fear in an enemy, causing it to flee in terror for $d.", description = "L'ombra lancia un urlo stridulo che terrorizza un nemico, facendolo fuggire per $d." },
    [437597] = { en = "The caster smashes the ground, inflicting $s1 Physical damage to all players and knocking them back.", description = "L'incantatore colpisce il suolo, infliggendo $s1 danni fisici a tutti i giocatori e respingendoli." },
    [437802] = { en = "The lightbearer channels their hope, making friendly targets within $A1 yards immune to silence.\r\n\r\nEnrages Screeching Terrors.", description = "Il portatore di Luce incanala la propria speranza, rendendo immuni al silenzio gli alleati entro $A1 metri.\r\n\r\nInfuria i Terrori Stridenti." },
    [437805] = { en = "Smite a target for $s1 Holy damage.", description = "Colpisce il bersaglio con Punizione, infliggendo $s1 danni sacri." },
    [437915] = { en = "The caster stuns targets for $d.", description = "L'incantatore stordisce i bersagli per $d." },
    [437933] = { en = "Balnazzar summons an infernal to interrupt a Scarlet Lightbearer, inflicting $s1 Fire damage within $A1 yards and stunning players hit for $D.", description = "Balnazzar evoca un infernale per interrompere un Portatore di Luce Scarlatto, infliggendo $s1 danni da fuoco entro $A1 metri e stordendo per $D i giocatori colpiti." },
    [438130] = { en = "Creates a pool of nauseating gas, which inflicts $438136s1 Nature damage to players within and reducing their attack and cast speed by $438136s2%.", description = "Crea una pozza di gas nauseabondo che infligge $438136s1 danni da natura ai giocatori al suo interno e riduce del $438136s2% la loro velocità d'attacco e di lancio." },
    [440892] = { en = "Curses the target for $d, reducing Magic resistances by $s1 and increases Magic damage taken by $s2%. Only one Curse per Warlock can be active on any one target.", description = "Maledice il bersaglio per $d, riducendone di $s1 le resistenze magiche e aumentando del $s2% i danni magici subiti. Un warlock può avere attiva una sola maledizione su ciascun bersaglio." },
    [444678] = { en = "Breathes molten lava at $x1 nearby enemies, instantly dealing $s1 Fire damage and reducing the target's casting speed by $s2% for $d.", description = "Sputa lava fusa contro $x1 nemici vicini, infliggendo istantaneamente $s1 danni da fuoco e riducendo del $s2% la velocità di lancio del bersaglio per $d." },
    [446327] = { en = "Increases damage done by $s1 and attack speed by $s2% for $d.", description = "Aumenta di $s1 i danni inflitti e del $s2% la velocità d'attacco per $d." },
    [446335] = { en = "Inspired by the Mojo of War, your size is increased and your Strength goes up by $s1 to match your new size.  Lasts $d.", description = "Ispirato dal Mojo della Guerra, aumenti di dimensioni e la tua Forza cresce di $s1 per adattarsi alla nuova stazza.  Dura $d." },
    [446695] = { en = "Increases critical strike chance by $s1%, spell damage by $s2, and all stats by $s3%. 120 minute duration.", description = "Aumenta del $s1% la probabilità di colpo critico, di $s2 i danni degli incantesimi e del $s3% tutte le statistiche. Dura 120 minuti." },
    [446785] = { en = "Restore $s1 Energy.", description = "Ripristina $s1 Energia." },
    [449933] = { en = "Increases spell critical strike chance by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico degli incantesimi." },
    [450512] = { en = "+$s1 Attack Power, up to $s3 increased damage from spells, and up to $s4 increased healing from spells.", description = "+$s1 potenza d'attacco, fino a $s3 danni aggiuntivi dagli incantesimi e fino a $s4 cure aggiuntive dagli incantesimi." },
    [450527] = { en = "Your spellcasts have a $h% chance to energize you for $450554s1 mana.", description = "I tuoi incantesimi hanno una probabilità del $h% di rigenerarti $450554s1 mana." },
    [450625] = { en = "Chance on melee autoattack and spellcast to increase your damage and healing done by magical spells and effects by up to $27499s1 for $27499d.", description = "Gli attacchi automatici in mischia e gli incantesimi hanno una probabilità di aumentare fino a $27499s1 i danni e le cure inflitti dagli incantesimi e dagli effetti magici per $27499d." },
    [457569] = { en = "Banishes the target, preventing all action but making it invulnerable for up to $d.  Only one target can be banished at a time.  Only works on Demons and Elementals.", description = "Bandisce il bersaglio, impedendogli ogni azione ma rendendolo invulnerabile per un massimo di $d. Può essere bandito un solo bersaglio alla volta. Funziona solo su Demoni ed Elementali." },
    [457847] = { en = "Stars fall from above, inflicting $s1 damage. ", description = "Cadono stelle dal cielo, infliggendo $s1 danni." },
    [458312] = { en = "Reduces all damage taken by $s1% for $d.  Once protected, you cannot be targeted by Divine Shield, Divine Protection, or Blessing of Protection again for $25771d.", description = "Riduce del $s1% tutti i danni subiti per $d. Dopo aver ricevuto protezione, non puoi essere nuovamente bersaglio di Scudo Divino, Protezione Divina o Benedizione della Protezione per $25771d." },
    [461327] = { en = "Causes your attacks to ignore $s2 of your target's Armor and increases the damage dealt by your Rupture ability by $s1%.  The amount of Armor reduced increases with your level.", description = "Fa ignorare ai tuoi attacchi $s2 armatura del bersaglio e aumenta del $s1% i danni inflitti dalla tua abilità Rottura. La quantità di armatura ignorata aumenta con il tuo livello." },
    [461607] = { en = "Leap atop your charger for $d, increasing movement speed by $s2%. Usable while indoors or in combat.", description = "Balza in sella al tuo destriero per $d, aumentando del $s2% la velocità di movimento. Utilizzabile al chiuso e in combattimento." },
    [461681] = { en = "Increased Feral Combat +$s1.", description = "Abilità di Combattimento Ferino aumentata di +$s1." },
    [462664] = { en = "Drains $s1 mana from those in the blast radius and does 50% of the mana drained in damage to the target.  Also Silences targets in the blast for $d.", description = "Prosciuga $s1 mana da chi si trova nell'area dell'esplosione e infligge al bersaglio danni pari al 50% del mana sottratto. Inoltre, silenzia per $d i bersagli nell'area." },
    [467826] = { en = "Unleash a poisonous sting that deals $s1 nature damage, and hits $s2 additional nearby targets.", description = "Scatena un pungiglione velenoso che infligge $s1 danni da natura e colpisce altri $s2 bersagli vicini." },
    [470280] = { en = "Deals $s1 Shadow damage split between enemy targets within $a1 yards in front of the caster. ", description = "Infligge $s1 danni da ombra, suddivisi tra i nemici entro $a1 metri di fronte all'incantatore." },
    [470462] = { en = "Launches shadow infused orbs towards a random player that travels out and return to it's origin. Players hit are inflicted with $s1 Shadow damage", description = "Lancia sfere intrise d'ombra contro un giocatore casuale; le sfere si allontanano e poi ritornano al punto di partenza. I giocatori colpiti subiscono $s1 danni da ombra." },
    [470497] = { en = "Carve a scale from Nefarian's hide. Only usable when Nefarian has been significantly weakened in battle.", description = "Stacca una scaglia dal dorso di Nefarian. Può essere usato solo quando Nefarian è stato indebolito a sufficienza durante lo scontro." },
    [1217084] = { en = "Increases all damage caused against targets in Silithus, Ahn'Qiraj, Eastern Plaguelands, and Naxxramas by $s1% and increases critical damage caused against targets in these areas by an additional $s2%.", description = "Aumenta dell'$s1% tutti i danni inflitti ai bersagli a Silithus, Ahn'Qiraj, nelle Terre Infette Orientali e a Naxxramas, e aumenta di un ulteriore $s2% i danni critici contro i bersagli in queste zone." },
    [1218367] = { en = "Hold up the Enchanted Torch and attempt to dispel the darkness near Karazhan Crypts.", description = "Solleva la Torcia Incantata e tenta di dissipare l'oscurità vicino alle Cripte di Karazhan." },
    [1220919] = { en = "Bonefang spews forth necrotic spittle, inflicting $333489s1 Shadow damage every $333489t sec. to enemies caught in the breath and reducing healing received by $333489s3%.\r\n\r\n", description = "Bonefang sputa saliva necrotica, infliggendo $333489s1 danni da ombra ai nemici investiti dal soffio ogni $333489t s e riducendo del $333489s3% le cure ricevute." },
}

for id, description in pairs(verifiedSpellDescriptions) do
